{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C40"],
      "claim": "Morphine, the closest morphinan analogue, has an oral bioavailability of only 20–25% in volunteers, placing the scaffold at the lower edge of the F≥20% threshold; the query's N-allyl and 6-keto modifications are expected to increase first-pass metabolism and reduce F below 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C16"],
      "claim": "Codeine, a 3-O-methyl morphinan, shows high oral bioavailability (80.5%) in healthy subjects, which would argue for high F in the opioid scaffold; however, the query lacks the 3-O-methyl group and instead has a 6-keto and N-allyl, which are associated with extensive first-pass metabolism, so this high-F evidence is not transferable to the query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "low",
  "decision_summary": "The query is naloxone, a morphinan with N-allyl and 6-keto modifications. The closest analogue morphine has oral bioavailability of 20–40%, near the F≥20% threshold, but naloxone's 6-keto and N-allyl groups are known to cause extensive first-pass metabolism, reducing F well below 20%. Therefore predict low.",
  "evidence_gaps": [
    "No direct naloxone oral bioavailability record in the evidence set.",
    "No low-F opioid analogue to directly anchor F<20%; the low prediction relies on structural extrapolation from morphine and known first-pass metabolism of naloxone."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

